import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"handl_plugin_lib_tag","description":"","frontmatter":{},"headers":[],"relativePath":"api/host/handl_plugin_lib_tag/index.md","filePath":"api/host/handl_plugin_lib_tag/index.md"}`),a={name:`api/host/handl_plugin_lib_tag/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="handl-plugin-lib-tag" tabindex="-1">handl_plugin_lib_tag <a class="header-anchor" href="#handl-plugin-lib-tag" aria-label="Permalink to “handl_plugin_lib_tag”">​</a></h1><h1 id="handl-plugin-lib-tag-1" tabindex="-1">handl-plugin-lib-tag <a class="header-anchor" href="#handl-plugin-lib-tag-1" aria-label="Permalink to “handl-plugin-lib-tag”">​</a></h1><p>The <strong>tagged-values</strong> capability as a composable <code>plugin-lib-*</code> leaf crate (ADR-0055 — Tagged Values).</p><p>Tagged values are the host primitive that lets the typechecker, units, capabilities, and provenance share one value space without collision (ADR-0032 &quot;types are values&quot;). A tagged value is a JSON object <code>{&quot;__tag__&quot;: &lt;name&gt;, ...payload}</code> minted by the host. Tagging is a <strong>host capability</strong>, not a user-constructible convention: the <code>__tag__</code> key is reserved (the eval engines reject it in user object literals), so the only way a value acquires a <code>__tag__</code> key is through this plugin&#39;s <code>tag.tag</code> host function. User code cannot forge a tagged value.</p><p>This crate has been migrated to the <code>op</code>/<code>handl</code> declaration form (ADR-0077 Phase 4). The tag interface is declared in <code>handl-packages/tag/tag.hnl</code> via <code>op</code> declarations, and the Rust tag/match/inspect logic is registered as handls (handlers) in an [<code>OpRegistry</code>]. The [<code>TagLibraryPlugin</code>] wraps the generic [<code>HandlLibraryPlugin</code>] with the op registry, eliminating the per-library <code>Module</code>/<code>Plugin</code> trait scaffolding.</p><p>This crate exposes the <code>tag</code> module with four callables — inspection and dispatch only; the <code>__tag__</code> mint producers (<code>tag.tag</code>, <code>tag.construct</code>) were deleted with the <code>__tag__</code>/<code>{tag}</code> bridge (ADR-0152 §Migration):</p><table tabindex="0"><thead><tr><th>Callable</th><th>Role</th></tr></thead><tbody><tr><td><code>tag.untag(v)</code></td><td>return the payload of a tagged value (inspection)</td></tr><tr><td><code>tag.tag_of(v)</code></td><td>return the tag name of a tagged value (inspection)</td></tr><tr><td><code>tag.is_tag(v)</code></td><td>test whether <code>v</code> is a tagged value (inspection)</td></tr><tr><td><code>tag.match_type(v, cases)</code></td><td><strong>dispatch</strong> on the type tag of <code>v</code> (ADR-0054)</td></tr></tbody></table><p><code>tag.match_type</code> is the user-facing surface of the ADR-0054 judgment op <code>match_type</code>, backed by a [<code>TypeRegistry</code>] with registry id <code>&quot;handl.canonical&quot;</code>.</p><p>Tagged values are still produced internally (law/rewrite/cell records); the inspection ops are available to any code that holds one — matching the capability discipline of ADR-0055 §1. Tag dispatch on <code>__tag__</code> identity is handled by the native <code>match</code> construct via tag patterns (<code>ok(v) =&gt; ...</code>), not a dedicated op (ADR-0077).</p><p>The [<code>TypeRegistry</code>] (in [<code>registry</code>]) is the type system machinery, not a callable — it is kept in Rust as pure data.</p><p>The [<code>TagModule</code>] re-export is preserved for backward compatibility with downstream crates (e.g. [<code>kit-canonical</code>]) that register <code>TagModule</code> directly.</p><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to “Modules”">​</a></h2><h3 id="handl-plugin-lib-tag-2" tabindex="-1"><a href="./handl_plugin_lib_tag.html"><code>handl_plugin_lib_tag</code></a> <a class="header-anchor" href="#handl-plugin-lib-tag-2" aria-label="Permalink to “handl_plugin_lib_tag”">​</a></h3><p><em>1 module, 3 constants, 4 functions, 4 statics, 6 structs</em></p><h3 id="registry" tabindex="-1"><a href="./registry.html"><code>registry</code></a> <a class="header-anchor" href="#registry" aria-label="Permalink to “registry”">​</a></h3><p><em>1 constant, 1 struct</em></p><h3 id="registry-typeregistry" tabindex="-1"><a href="./registry/TypeRegistry.html"><code>registry::TypeRegistry</code></a> <a class="header-anchor" href="#registry-typeregistry" aria-label="Permalink to “registry::TypeRegistry”">​</a></h3><p><em>1 function</em></p>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};